38	    public long insert(String model, String fromVersion, String toVersion, int ratio,
39	                       int sampleFloor, int failureThresholdPercent) {
40	        KeyHolder keyHolder = new GeneratedKeyHolder();
41	        jdbc.update(con -> {
42	            PreparedStatement ps = con.prepareStatement(
43	                    "INSERT INTO release_order (version, model, from_version, to_version, ratio, status,"
44	                            + " sample_floor, failure_threshold_percent, monitor_round, active_model)"
45	                            + " VALUES (1, ?, ?, ?, ?, 'ACTIVE', ?, ?, 1, ?)",
