package com.example.starter.firmware.domain;

/**
 * 设备登记信息。
 *
 * @param deviceId               设备唯一标识
 * @param model                  设备型号，登记后不可修改
 * @param currentVersion         设备当前固件版本
 * @param bucketNo               灰度分桶号，取值0~99，登记后不可修改
 * @param securityFloor          安全底线（非负整数，单调不降）：登记时首次设定，维护只能提升，成功安装取两者最大
 * @param securityProfileVersion 安全档案版本，从1开始，维护与首次成功安装各加一
 */
public record Device(String deviceId, String model, String currentVersion, int bucketNo,
                     int securityFloor, int securityProfileVersion) {
}

package com.example.starter.firmware.domain;

/**
 * 设备投放任务，同设备同发布单最多一条。
 *
 * @param id                   任务ID
 * @param releaseId            所属发布单ID
 * @param deviceId             设备ID
 * @param status               任务状态
 * @param firstResult          首次回执结果（SUCCESS/FAILED），未回执为 null
 * @param targetSecurityIndex  任务创建时冻结的目标安全索引，此后不随发布单或设备底线变化
 * @param receiptSecurityIndex 首次回执携带的证明索引（安装证据），未回执或未提供为 null
 */
public record RolloutTask(long id, long releaseId, String deviceId, TaskStatus status,
                          ReceiptResult firstResult, Integer targetSecurityIndex,
                          Integer receiptSecurityIndex) {
}

